#!/usr/bin/env python3
"""
ONE-FILE REGRESSION PROJECT RUNNER

This file contains the complete project source embedded inside it.
It extracts the project to a temporary directory and runs selftest.py.

Usage:
    python run_all_selftests.py

Requirements:
    - Python 3.10+
    - git
    - pytest

It does not require an OpenRouter API key because selftest.py primarily
uses --no-llm and also tests malformed-LLM fallback locally.
"""
import base64
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

FILES = {
    'agent.py': '',
    'recorder.py': '',
    'casegen.py': '',
    'contract.py': '',
    'llm_client.py': '',
    'emit.py': '',
    'mutation_engine.py': '',
    'regression_runtime.py': '',
    'selftest.py': '',
    'rtgen.py': '',
    'mutation_check.py': '',
    'test_api_regression.py': '',
}

def main():
    root = Path(tempfile.mkdtemp(prefix="regression_project_"))
    try:
        for name, data in FILES.items():
            path = root / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(base64.b64decode(data))

        print("=" * 70)
        print("COMPLETE REGRESSION PROJECT SELF-TEST")
        print("=" * 70)
        print("Project extracted to:", root)
        print("Running: python selftest.py")
        print("=" * 70)

        env = os.environ.copy()
        env.pop("OPENROUTER_API_KEY", None)
        env["PYTHONDONTWRITEBYTECODE"] = "1"

        result = subprocess.run(
            [sys.executable, str(root / "selftest.py")],
            cwd=root,
            env=env,
        )

        print("=" * 70)
        if result.returncode == 0:
            print("RESULT: ALL SELF-TESTS PASSED")
        else:
            print("RESULT: SELF-TEST FAILED")
            print("Exit code:", result.returncode)
        print("=" * 70)
        return result.returncode
    finally:
        shutil.rmtree(root, ignore_errors=True)

if __name__ == "__main__":
    raise SystemExit(main())
